def run_probe(binary: Path, input_text: str) -> list[str]:
    """Returns the list of delivered frame descriptions, in order."""
    try:
        result = subprocess.run(
            [str(binary), input_text], capture_output=True, text=True, check=True, timeout=30
        )
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired) as err:
        raise RuntimeError(f"probe {binary.name} failed: {err}") from err
    lines = result.stdout.strip().splitlines()
    if not lines or not lines[0].startswith("frames:"):
        raise RuntimeError(f"probe {binary.name} malformed output: {result.stdout!r} {result.stderr!r}")
    try:
        count = int(lines[0].removeprefix("frames:"))
    except ValueError as err:
        raise RuntimeError(f"probe {binary.name} bad frame count: {lines[0]!r}") from err
    frames = lines[1 : 1 + count]
    if count < 0 or len(frames) != count:
        raise RuntimeError(f"probe {binary.name} count/line mismatch: {lines!r}")
    return frames

