private let ticketMask: UInt64 = 0xFF_FFFF_FFFF
private let laneMask: UInt64 = 0xFFFF
private let tierMask: UInt64 = 0xFF

func makeCommandWord(ticket: UInt64, lane: UInt64, tier: UInt64) -> UInt64 {
    precondition(ticket & ~ticketMask == 0, "ticket exceeds 40 bits")
    precondition(lane & ~laneMask == 0, "lane exceeds 16 bits")
    precondition(tier & ~tierMask == 0, "tier exceeds 8 bits")
    return ((ticket & ticketMask) << 24) | ((lane & laneMask) << 8) | (tier & tierMask)
}

