public func refreshAll(ids: [String]) async throws -> [String: Summary] {
    let fetchSummary = self.fetchSummary
    var summaries: [String: Summary] = [:]
    var index = ids.startIndex
    while index < ids.endIndex {
        try Task.checkCancellation()
        let end = ids.index(index, offsetBy: 4, limitedBy: ids.endIndex) ?? ids.endIndex
        let chunk = ids[index..<end]
        try await withThrowingTaskGroup(of: (String, Summary).self) { group in
            for id in chunk {
                group.addTask {
                    (id, try await fetchSummary(id))
                }
            }
            for try await (id, summary) in group {
                summaries[id] = summary
            }
        }
        index = end
    }
    return summaries
}

