public static func isWellFormed(_ code: String) -> Bool {
    let parts = code.split(separator: "-")
    guard parts.count == 2, parts[0].count == 4, parts[1].count == 6 else { return false }
    let lettersValid = parts[0].allSatisfy { $0 >= "A" && $0 <= "Z" }
    let digitsValid = parts[1].allSatisfy { $0.isNumber }
    return lettersValid && digitsValid
}

