def _strip_balanced_parens(s: str) -> str:
    while s.startswith("("):
        depth = 0
        for i, ch in enumerate(s):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    s = s[i + 1:].lstrip()
                    break
        else:
            break
    return s

